<div class="section-actions"><p class="muted">Organization passwords. Values remain hidden until you choose Reveal.</p><?php if($canWrite): ?><a class="button" href="<?= $link('/organizations/'.$organization['id'].'/passwords/new') ?>">New password</a><?php endif; ?></div><section class="card"><?php if(!$passwords): ?><p>No passwords yet.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>Name</th><th>Username</th><th>Visibility</th></tr></thead><tbody><?php foreach($passwords as $p): ?><tr><td><a href="<?= $link('/passwords/'.$p['id']) ?>"><?= $e($p['title']) ?></a></td><td><?= $e($p['username']) ?></td><td><?= $p['visibility']==='client'?'Client visible':'Internal only' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
